plugins {
    alias(libs.plugins.android.library)
    // For the tests, which draw every icon with QeetrixIcon; the module itself declares no composable.
    alias(libs.plugins.kotlin.compose)
    alias(libs.plugins.ktlint)
    `maven-publish`
}

// Maven coordinates com.qeetgroup:qeetrix-icons-extended, released with com.qeetgroup:qeetrix at the same version
// (docs/decisions.md). Every @qeetrix/icons icon the core library doesn't carry, generated by qeetrix-gen
// (Scripts/generate-tokens) — nothing here is written by hand except this file and the tests.
group = "com.qeetgroup"
version = providers.gradleProperty("qeetrix.version").get()

android {
    namespace = "com.qeetgroup.qeetrix.icons.extended"
    compileSdk = 37

    defaultConfig {
        minSdk = 29
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    buildFeatures {
        buildConfig = false
    }

    testOptions {
        unitTests {
            isIncludeAndroidResources = true
            all {
                // The tests compare the module with the upstream snapshot.
                it.systemProperty("qeetrix.root", rootDir.absolutePath)
                it.jvmArgs("--add-exports=java.base/jdk.internal.access=ALL-UNNAMED", "--add-opens=java.base/java.io=ALL-UNNAMED")
            }
        }
    }

    publishing {
        singleVariant("release") {
            withSourcesJar()
        }
    }

    lint {
        warningsAsErrors = true
        abortOnError = true
        checkDependencies = false
        disable += setOf("GradleDependency", "NewerVersionAvailable", "AndroidGradlePluginVersion", "ObsoleteLintCustomCheck")
    }
}

kotlin {
    explicitApi()
    compilerOptions {
        jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17)
    }
}

ktlint {
    version.set(libs.versions.ktlint.engine)
    android.set(false)
    filter {
        // The icons are generated and verified against the generator instead.
        exclude { it.file.path.contains("/src/main/") }
    }
}

dependencies {
    // QeetrixIconName, which every icon here is, and QeetrixIcon, which draws them.
    api(project(":qeetrix"))
    // The versions of the Compose artifacts :qeetrix exposes, as an app declares them (the BOM is :qeetrix's own
    // implementation detail, so it doesn't reach this module's compile classpath by itself).
    implementation(platform(libs.compose.bom))

    testImplementation(platform(libs.compose.bom))
    testImplementation(libs.junit4)
    testImplementation(libs.robolectric)
    testImplementation(libs.compose.ui.test.junit4)
    debugImplementation(platform(libs.compose.bom))
    debugImplementation(libs.compose.ui.test.manifest)
}

// As qeetrix: lock what reaches an app (refresh with ./gradlew :qeetrix-icons-extended:dependencies --write-locks).
dependencyLocking {
    lockMode.set(LockMode.STRICT)
}
configurations.matching { it.name == "releaseCompileClasspath" || it.name == "releaseRuntimeClasspath" }.configureEach {
    resolutionStrategy.activateDependencyLocking()
}

publishing {
    publications {
        register<MavenPublication>("release") {
            artifactId = "qeetrix-icons-extended"
            afterEvaluate { from(components["release"]) }
            versionMapping {
                usage("java-api") { fromResolutionOf("releaseCompileClasspath") }
                usage("java-runtime") { fromResolutionOf("releaseRuntimeClasspath") }
            }
            pom {
                name.set("Qeetrix for Android — extended icons")
                description.set(
                    "Every @qeetrix/icons icon beyond Qeetrix for Android's core set, by name: QeetrixIconName.AlarmClock. " +
                        "Each icon is its own class, so R8 keeps only the icons an app uses.",
                )
                url.set("https://github.com/qeetgroup/qeetrix-android")
                organization {
                    name.set("Qeet Group")
                    url.set("https://qeet.in")
                }
                scm {
                    url.set("https://github.com/qeetgroup/qeetrix-android")
                    connection.set("scm:git:https://github.com/qeetgroup/qeetrix-android.git")
                }
                // The drawings are @qeetrix/icons' (MIT, with Lucide's ISC notice); their licence ships in com.qeetgroup:qeetrix,
                // which this module depends on.
                licenses {
                    license {
                        name.set("MIT License")
                        url.set("https://opensource.org/license/mit")
                        distribution.set("repo")
                    }
                }
            }
        }
    }
    repositories {
        maven {
            name = "releaseCandidate"
            url = uri(rootProject.layout.buildDirectory.dir("release-candidate/maven"))
        }
        providers.gradleProperty("qeetrix.registry.url").orNull?.let { registryUrl ->
            maven {
                name = "registry"
                url = uri(registryUrl)
                credentials(PasswordCredentials::class)
            }
        }
    }
}
